import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Provider v1 to v2 migration","description":"","frontmatter":{},"headers":[],"relativePath":"release/migrations/v1-to-v2.md","filePath":"release/migrations/v1-to-v2.md"}'),i={name:"release/migrations/v1-to-v2.md"};function d(s,e,n,c,l,v){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="provider-v1-to-v2-migration" tabindex="-1">Provider v1 to v2 migration <a class="header-anchor" href="#provider-v1-to-v2-migration" aria-label="Permalink to &quot;Provider v1 to v2 migration&quot;">​</a></h1><p>Provider v1 and provider v2 use the same Registry address but implement different Form epochs.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Form epoch</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td><code>1.x</code></td><td><code>forms.takoform.com/v1alpha1</code></td><td>published Legacy</td><td>recovery and existing state</td></tr><tr><td><code>2.0.0</code></td><td><code>forms.takoform.com/v1alpha2</code></td><td>published compatibility predecessor</td><td>retained nine-Form v1alpha2 line</td></tr><tr><td><code>2.1.1</code></td><td><code>forms.takoform.com/v1beta1</code></td><td>Registry-published retained Provider 2 release; Beta Host API and Experimental Forms</td><td>retained Edge Form Family line</td></tr></tbody></table><p>Provider v2.1 carries the retained Experimental Edge Platform Family over Beta Host API <code>forms.takoform.com/v1beta1</code>. Provider v2.1.1 was the last Provider 2 release and remains Registry-published immutable history; Provider 3.0.0 is retained 31-Form aggregate history and Provider 4.0.0 is the current published provider. The v2.1.1 release descriptor remains <code>candidate-only</code> metadata by design after owner publication, while its Registry publication is independently verified by readback (<a href="./../../spec/decisions/0035-beta-contracts-ship-in-stable-provider-v2-1.html">decision 0035</a>). Existing Beta state remains bound to its exact Beta FormRef and codec when a future Stable <code>1.0.0</code> identity becomes the create default; refresh never performs that migration implicitly.</p><p>This guide records the v1-to-v2 boundary. A later upgrade must also follow the <a href="./v2-to-v3.html">Provider v2 to v3 migration boundary</a>.</p><p>This boundary is intentionally fail-closed. Provider v2 does not upgrade v1 state in place because definition and package identities changed and the new contract may have different semantics even when the Terraform resource type is the same.</p><ol><li>Pin provider v1 and refresh the Legacy resource.</li><li>Capture non-secret desired configuration and required public outputs.</li><li>Create the corresponding v1alpha2 resource under provider v2, or import a host resource only when the host proves it conforms to the exact v1alpha2 FormRef.</li><li>Move consumers to the new resource and verify host observation.</li><li>Delete the Legacy resource through provider v1 when rollback is no longer required.</li></ol><p>Do not edit state JSON, substitute FormRef digests, or use an automatic state upgrader. If recovery is needed, return to the exact provider-v1 constraint and the retained Legacy host lane.</p>',8)])])}const p=t(i,[["render",d]]);export{m as __pageData,p as default};
